<?php require 'config/db.php';auth();$error='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();admin();$action=$_POST['action']??'';$id=(int)($_POST['id']??0);if($action==='delete'){$s=$pdo->prepare('SELECT COUNT(*) FROM patients WHERE puskesmas_id=?');$s->execute([$id]);if($s->fetchColumn())$error='Puskesmas masih memiliki pasien dan tidak dapat dihapus.';else{$s=$pdo->prepare('DELETE FROM puskesmas WHERE id=?');$s->execute([$id]);redirect('puskesmas.php');}}elseif($action==='save'){$nama=trim($_POST['nama']??'');if($nama==='')$error='Nama wajib diisi.';else{try{if($id){$s=$pdo->prepare('UPDATE puskesmas SET nama=?,alamat=?,kecamatan=?,telepon=? WHERE id=?');$s->execute([$nama,$_POST['alamat']??'',$_POST['kecamatan']??'',$_POST['telepon']??'',$id]);}else{$s=$pdo->prepare('INSERT INTO puskesmas(nama,alamat,kecamatan,telepon) VALUES(?,?,?,?)');$s->execute([$nama,$_POST['alamat']??'',$_POST['kecamatan']??'',$_POST['telepon']??'']);}redirect('puskesmas.php');}catch(PDOException $ex){$error='Nama Puskesmas sudah ada atau data tidak valid.';}}}}$rows=$pdo->query('SELECT * FROM puskesmas ORDER BY nama')->fetchAll();include 'partials/header.php';?><div class="heading"><h1>Data Puskesmas</h1><p>Daftar awal berdasarkan referensi gambar; lengkapi dan verifikasi dengan daftar resmi instansi.</p></div><?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif;?><?php if(($_SESSION['role']??'')==='admin'):?><section class="panel"><div class="panel-title">Tambah Puskesmas</div><div class="panel-body"><form method="post" class="form-grid"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="save"><div class="field"><label>Nama Puskesmas</label><input name="nama" required></div><div class="field"><label>Kecamatan</label><input name="kecamatan"></div><div class="field"><label>Alamat</label><input name="alamat"></div><div class="field"><label>Telepon</label><input name="telepon"></div><button class="btn">Tambah Puskesmas</button></form></div></section><?php endif;?><section class="panel"><div class="panel-title">Daftar Puskesmas</div><div class="panel-body table-wrap"><table><thead><tr><th>No</th><th>Nama</th><th>Kecamatan</th><th>Alamat</th><th>Telepon</th><th>Aksi</th></tr></thead><tbody><?php foreach($rows as $i=>$r):?><tr><td><?=$i+1?></td><td><?=e($r['nama'])?></td><td><?=e($r['kecamatan'])?></td><td><?=e($r['alamat'])?></td><td><?=e($r['telepon'])?></td><td><?php if(($_SESSION['role']??'')==='admin'):?><form method="post" class="inline"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn danger small" data-confirm="Hapus Puskesmas ini?">Hapus</button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></section><?php include 'partials/footer.php';?>
